      "type": "object",
      "additionalProperties": false,
      "required": [
        "recipe",
        "components",
        "parameters"
      ],
      "properties": {
        "recipe": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
        },
        "components": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "include",
            "exclude"
          ],
          "properties": {
            "include": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^(capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
              }
            },
            "exclude": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^(capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
              }
            }
          }
        },
        "parameters": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(artifact|capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
          },
          "additionalProperties": {
            "type": "object"
          }
        }
      }
    },
    "recipe_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "configuration_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "resolved_components": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "contains": {
        "type": "object",
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^artifact\\."
          }
        }
      },
      "minContains": 1,
      "maxContains": 1,
      "allOf": [
        {
          "contains": {
            "type": "object",
            "required": [
              "id"
            ],
            "properties": {
              "id": {
                "type": "string",
                "pattern": "^topology\\."
              }
            }
          },
          "minContains": 0,
          "maxContains": 1
        }
        ,{
          "contains": {
            "type": "object",
            "required": ["id"],
            "properties": {"id": {"type": "string", "pattern": "^workspace\\."}}
          },
          "minContains": 0,
          "maxContains": 1
        }
      ],
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "version",
          "descriptor_sha256"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^(foundation|artifact|capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
          },
          "version": {
            "type": "integer",
            "minimum": 1
          },
          "descriptor_sha256": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          }
        }
      }
    },
    "files": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "destination",
          "component",
          "ownership",
          "materialized_sha256"
        ],
        "properties": {
          "destination": {
            "type": "string",
            "pattern": "^(?!\\.template-composition(?:$|/(?:lock|transaction)\\.json(?:/|$)|/staging(?:/|$)))(?!\\.[aA][gG][eE][nN][tT]-[pP][oO][lL][iI][cC][yY](?:$|/|\\.[yY][mM][lL](?:/|$)|\\.[lL][oO][cC][kK](?:/|$)))(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.?(?:/|$))(?!.*(?:^|/)\\.[gG][iI][tT](?:/|$))[A-Za-z0-9_.][A-Za-z0-9._-]*(?:/[A-Za-z0-9_.][A-Za-z0-9._-]*)*$"
          },
          "component": {
            "type": "string",
            "pattern": "^(foundation|artifact|capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
          },
          "ownership": {
            "enum": [
              "managed",
              "seed",
              "generated"
            ]
          },
          "materialized_sha256": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          }
        }
      }
    }
  }
}

