{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://templates.moukaeritai.work/schemas/composition/composition-lock.schema.json",
  "title": "Resolved composition lock",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "source",
    "intent",
    "recipe_sha256",
    "configuration_sha256",
    "resolved_components",
    "files"
  ],
  "properties": {
    "schema_version": {
      "const": 2
    },
    "source": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "repository",
        "revision"
      ],
      "properties": {
        "repository": {
          "const": "TakashiSasaki/templates"
        },
        "revision": {
          "type": "string",
          "pattern": "^(?!0{40}$)[0-9a-f]{40}$"
        }
      }
    },
    "intent": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "recipe",
        "components",
        "parameters"
      ],
      "properties": {
        "recipe": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
        },
        "components": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "include",
            "exclude"
          ],
          "properties": {
            "include": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^(capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
              }
            },
            "exclude": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^(capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
              }
            }
          }
        },
        "parameters": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(artifact|capability|lifecycle|topology|workspace)\\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
          },
          "additionalProperties": {
            "type": "object"
          }
        }
      }
    },
    "recipe_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "configuration_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "resolved_components": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "contains": {
        "type": "object",
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^artifact\\."
          }
        }
      },
      "minContains": 1,
      "maxContains": 1,
      "allOf": [
        {
          "contains": {
            "type": "object",
            "required": [
              "id"
            ],
            "properties": {
              "id": {
